import type { LearningHistoryInsert } from '@/api/learningHistories'

/** 저장 진행 상태. 'error'면 버퍼에 미전송분이 남아 있다. */
export type SaveState = 'idle' | 'saving' | 'error'

export type RetryOptions = {
  /** 총 시도 횟수(첫 시도 포함). 기본 3. */
  attempts?: number
  /** 첫 재시도까지의 대기(ms). 이후 2배씩 증가. 기본 500. */
  baseDelayMs?: number
  /** 대기 구현. 테스트에서 주입해 실제 지연 없이 검증한다. */
  sleep?: (ms: number) => Promise<void>
}

const defaultSleep = (ms: number) => new Promise<void>((resolve) => setTimeout(resolve, ms))

/** 지수 백오프로 재시도한다. 일시적인 네트워크 단절을 흡수하는 용도. */
export async function withRetry<T>(fn: () => Promise<T>, options: RetryOptions = {}): Promise<T> {
  const { attempts = 3, baseDelayMs = 500, sleep = defaultSleep } = options
  let lastError: unknown

  for (let attempt = 0; attempt < attempts; attempt += 1) {
    try {
      return await fn()
    } catch (e) {
      lastError = e
      if (attempt < attempts - 1) {
        await sleep(baseDelayMs * 2 ** attempt)
      }
    }
  }

  throw lastError
}

export type LearningHistoryBufferOptions = RetryOptions & {
  /** 최종 전송 실패 시 호출. 로깅용. */
  onError?: (error: unknown) => void
}

export type LearningHistoryBuffer = {
  push: (item: LearningHistoryInsert) => void
  size: () => number
  /** 현재 버퍼 내용의 사본. 검사·디버그용. */
  peek: () => LearningHistoryInsert[]
  /** @returns 전송 성공 여부. 보낼 것이 없으면 true. */
  flush: (send: (items: LearningHistoryInsert[]) => Promise<void>) => Promise<boolean>
}

/**
 * 학습 이력 전송 버퍼.
 *
 * `flush`가 최종 실패하면 꺼냈던 항목을 **버퍼 앞으로 되돌린다**. 되돌리지 않으면
 * 재시도할 수단이 없어 세션이 통째로 사라진다 — 실제 유실 사례의 직접 원인이었다
 * (docs/plan-learning-history-loss.md §2 I1). 되돌린 항목은 재시도 버튼이나
 * 다음 세션 종료 시 함께 전송된다.
 */
export function createLearningHistoryBuffer(
  options: LearningHistoryBufferOptions = {}
): LearningHistoryBuffer {
  const { onError, ...retryOptions } = options
  const items: LearningHistoryInsert[] = []

  return {
    push: (item) => {
      items.push(item)
    },
    size: () => items.length,
    peek: () => [...items],
    flush: async (send) => {
      if (items.length === 0) return true

      // 전송 중 새로 쌓이는 항목과 섞이지 않도록 통째로 꺼낸다.
      const pending = items.splice(0, items.length)

      try {
        await withRetry(() => send(pending), retryOptions)
      } catch (e) {
        // 전송 실패분이 먼저 오도록 앞에 붙인다 (기록 순서 유지).
        items.unshift(...pending)
        onError?.(e)
        return false
      }

      return true
    },
  }
}
