import { useCallback, useEffect, useRef } from 'react'

/**
 * 페이지가 실제로 보이는 동안의 경과 시간을 추적한다.
 *
 * visibilitychange 이벤트만 믿으면 `visible` 이벤트 하나를 놓쳤을 때
 * (Suspense 재-suspend 중 리스너 부재, 브라우저 절전·가림 경계 등)
 * 이후 시간이 전부 hidden으로 차감되어 세션 시간이 수십 초로 기록되는 문제가 있었다.
 * 그래서 `document.hidden`을 진실로 삼아, 값을 읽거나 사용자 입력이 들어올 때
 * 내부 상태를 실제 가시성과 다시 맞춘다.
 */
export function useForegroundDuration() {
  // eslint-disable-next-line react-hooks/purity
  const startTimeRef = useRef(Date.now())
  const hiddenDurationRef = useRef(0)
  const hiddenAtRef = useRef<number | null>(null)

  /** 내부 hidden 상태를 `document.hidden`과 동기화한다. 놓친 이벤트를 보정한다. */
  const syncVisibility = useCallback(() => {
    const now = Date.now()
    if (document.hidden) {
      if (hiddenAtRef.current === null) hiddenAtRef.current = now
    } else if (hiddenAtRef.current !== null) {
      hiddenDurationRef.current += now - hiddenAtRef.current
      hiddenAtRef.current = null
    }
  }, [])

  useEffect(() => {
    // 마운트 시점에도 한 번 맞춘다 (백그라운드 탭에서 열린 경우 등).
    syncVisibility()
    document.addEventListener('visibilitychange', syncVisibility)
    return () => document.removeEventListener('visibilitychange', syncVisibility)
  }, [syncVisibility])

  const getStartTime = useCallback(() => startTimeRef.current, [])

  const getDuration = useCallback(() => {
    syncVisibility()
    const now = Date.now()
    const hiddenNow = hiddenAtRef.current !== null ? now - hiddenAtRef.current : 0
    return now - startTimeRef.current - hiddenDurationRef.current - hiddenNow
  }, [syncVisibility])

  const resetDuration = useCallback(() => {
    startTimeRef.current = Date.now()
    hiddenDurationRef.current = 0
    hiddenAtRef.current = document.hidden ? startTimeRef.current : null
  }, [])

  /**
   * 사용자 입력이 있었음을 알린다. 입력이 있으면 페이지는 실제로 보이는 상태이므로
   * 놓친 `visible` 이벤트로 남아 있던 hidden 구간을 여기서 닫는다.
   */
  const markActive = useCallback(() => {
    syncVisibility()
  }, [syncVisibility])

  return { getStartTime, getDuration, resetDuration, markActive }
}
